content.text:
                    link, seq, j = (a, b), path, i
                else:
                    link, seq, j = (b, a), rev, n - 2 - i
                e = index.get(link)
                if e is None:
                    raise Invalid()
                u = seq[j]
                v = seq[j + 1]
                if j > 0:
                    left = self._var(index, seq[j - 1], u)
                else:
                    left = None
                if j + 2 < n:
                    right = self._var(index, v, seq[j + 2])
                else:
                    right = None
                self.ctx[e].append((left, right, count))

    @staticmethod
    def _var(index, u, v):
        link, forward = key_dir(u, v)
        var = index.get(link)
        if var is None:
            raise Invalid()
        return (var, forward)

    def _prepare(self):
        """Scope of every potential plus its pattern -> count aggregation."""
        for e in range(self.m):
            seen = [False] * self.m
            seen[e] = True
            scope = [e]
            for left, right, _count in self.ctx[e]:
                for ctx in (left, right):
                    if ctx is not None and not seen[ctx[0]]:
                        seen[ctx[0]] = True
                        scope.append(ctx[0])
            self.scopes[e] = tuple(scope)
            pos = {}
            for i, var in enumerate(scope):
                pos[var] = i
            table = {}
            cache = {}
            for left, right, count in self.ctx[e]:
                dims = []
                if left is not None:
                    dims.append((pos[left[0]], left[1]))
                if right is not None:
                    dims.append((pos[right[0]], right[1]))
                nd = len(dims)
                listed = cache.get(nd)
                if listed is None:
                    listed = [list(item) for item in
                              itertools.product(STATES, repeat=nd)]
                    cache[nd] = listed
                for values in listed:
                    if left is None:
                        lv = C2P
                    else:
                        raw = values[0]
                        lv = raw if left[1] else 2 - raw
                    if right is None:
                        rv = P2C
                    else:
                        raw = values[nd - 1]
                        rv = raw if right[1] else 2 - raw
                    g = G_TABLE[lv][rv]
                    key = tuple([(pos[e], g)] +
                                [(dims[i][0], values[i]) for i in range(nd)])
                    table[key] = table.get(key, 0) + count
            self.patterns[e] = table

    def build_phis(self):
        """Tables of the integer potentials phi_e over each declared scope."""
        self._prepare()
        phis = []
        for e in range(self.m):
            scope = self.scopes[e]
            k = len(scope)
            size = 3 ** k
            stride = [3 ** (k - 1 - i) for i in range(k)]
            values = [0] * size
            offsets = {}
            for key, count in self.patterns[e].items():
                fixed = 0
                used = []
                for position, value in key:
                    fixed += stride[position] * value
                    used.append(position)
                mask = tuple(sorted(used))
                free = offsets.get(mask)
                if free is None:
                    free = [0]
                    for i in range(k):
                        if i in mask:
                            continue
                        step = stride[i]
                        free = [f + t * step for f in free for t in STATES]
                    offsets[mask] = free
                for f in free:
                    values[fixed + f] += count
            phis.append((scope, values))
        return phis


