def check_width(phis, order_vars):
    """order must be an elimination of the scope graph with width <= 4."""
    n = len(phis)
    adj = [set() for _ in range(n)]
    for scope, _values in phis:
        for i in range(len(scope)):
            for j in range(i + 1, len(scope)):
                a, b = scope[i], scope[j]
                adj[a].add(b)
                adj[b].add(a)
    for var in order_vars:
        neigh = adj[var]
        if len(neigh) > MAX_NEIGHBORS:
            raise Invalid()
        items = list(neigh)
        for other in items:
            adj[other].discard(var)
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                adj[items[i]].add(items[j])
                adj[items[j]].add(items[i])
        adj[var] = set()


