    """Elimination plan: pure structure, reusable for every clamp."""
    scopes = [list(scope) for scope, _values in phis]
    alive = [True] * len(scopes)
    steps = []
    for var in order_vars:
        involved = [fi for fi in range(len(scopes))
                    if alive[fi] and var in scopes[fi]]
        if not involved:
            continue
        union = []
        for fi in involved:
            for x in scopes[fi]:
                if x not in union:
                    union.append(x)
        others = [x for x in union if x != var]
        digits = [list(item) for item in
                  itertools.product(STATES, repeat=len(union))]
        ustr = [3 ** (len(union) - 1 - i) for i in range(len(union))]
        maps = []
