            for d in digits:
                idx = 0
                for j, p in enumerate(where):
                    idx += d[p] * fstr[j]
                table.append(idx)
            maps.append((fi, table))
        ostr = [3 ** (len(others) - 1 - i) for i in range(len(others))]
        owere = [union.index(x) for x in others]
